    "C32","C35","C37","C38","C40","C41"
  ],
  "claims": [
    {
      "claim": "All L1 records report oral bioavailability values at or above approximately 34% or qualitative good/complete bioavailability; no L1 record affirmatively supports F < 20%.",
      "card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15","C16","C17"]
    },
    {
      "claim": "Nitro/ester-containing analogs nitrendipine and nifedipine show F of 54% and 52–100% in cirrhosis; L2 context adds predicted/observed values of 57% and 90–91%, reinforcing that these motifs are compatible with F ≥ 20%.",
      "card_ids": ["C09","C11","C14","C23","C25","C28"]
    },
    {
      "claim": "L3 oral exposure records for metronidazole, the active moiety of the query benzoate ester, show substantial systemic Cmax and AUC after oral dosing (e.g., Cmax 6.66–6.77 µg/mL after 250 mg; AUC0-∞ 75.23 µg·h/mL; steady-state Cmax 27.6 µg/mL), consistent with good oral absorption.",
      "card_ids": ["C32","C35","C37","C38","C40","C41"]
    },
    {
      "claim": "L3 records for close nitroimidazole analogs ornidazole and nimorazole also show measurable oral Cmax (9.84–11.89 µg/mL and 34.4 µg/mL), supporting class-level oral exposure.",
      "card_ids": ["C33","C34","C36","C39","C42"]
    },
    {
      "claim": "The only negative-direction L2 record (ebastine low absolute F due to extensive CYP metabolism) is structurally distinct and low transferability; it does not provide affirmative threshold-relevant evidence for F < 20%.",
      "card_ids": ["C31"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
